import{_ as t,o as r,c as a,a3 as n}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Team and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/team.md","filePath":"user/center/team.md"}'),o={name:"user/center/team.md"};function s(i,e,d,h,c,l){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="team-and-permissions" tabindex="-1">Team and permissions <a class="header-anchor" href="#team-and-permissions" aria-label="Permalink to &quot;Team and permissions&quot;">​</a></h1><p>You need the <strong>users</strong> permission to manage the team.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><ul><li>The <strong>owner</strong> (primary user) can do everything, cannot be changed or removed, and must re-enter their password to open the dashboard.</li><li>Everyone else is a <strong>team member</strong> with specific permissions.</li></ul><h2 id="adding-someone" tabindex="-1">Adding someone <a class="header-anchor" href="#adding-someone" aria-label="Permalink to &quot;Adding someone&quot;">​</a></h2><p><strong>Users → New.</strong> Enter their phone number and tick their permissions.</p><ul><li>You can only give permissions you have yourself.</li><li>You cannot change your own permissions.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Examples</th></tr></thead><tbody><tr><td>Services</td><td>Manage riding, visit, event, resort, horse care, horse service, training, membership or stabling services (one permission each)</td></tr><tr><td>Purchases</td><td>View purchases for each service type; see prices; see other trainers&#39; sales; see sales without a trainer</td></tr><tr><td>Reservations</td><td>Manage reservations; edit reservations</td></tr><tr><td>Clients</td><td>Manage blocked clients; export clients</td></tr><tr><td>Horses</td><td>Manage the center&#39;s horses</td></tr><tr><td>Business</td><td>Promotions; analytics; ratings; payouts; export purchases; manage users</td></tr></tbody></table><h2 id="removing-someone" tabindex="-1">Removing someone <a class="header-anchor" href="#removing-someone" aria-label="Permalink to &quot;Removing someone&quot;">​</a></h2><p>Removing a team member signs them out of the dashboard immediately. If they belong to no other center, their account is removed.</p><h2 id="your-own-profile" tabindex="-1">Your own profile <a class="header-anchor" href="#your-own-profile" aria-label="Permalink to &quot;Your own profile&quot;">​</a></h2><p>The owner can change their name and dashboard password. To change a password that is already set, enter the current one first. The phone number cannot be changed here.</p><h2 id="deleting-the-center-account" tabindex="-1">Deleting the center account <a class="header-anchor" href="#deleting-the-center-account" aria-label="Permalink to &quot;Deleting the center account&quot;">​</a></h2><p>Only the owner can delete the account. This removes the center and signs out its whole team; team members who belong to no other center have their accounts removed. An admin can restore a deleted center together with its team.</p><p>You cannot delete the account while there are upcoming pending or confirmed reservations, or a pending payout or unsettled balance. Cancel the reservations and settle the payout first.</p>',16)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
